for key,author,title,year,url,scope,dates,level in data:
 verified=level!='unverified'
 evidence.append(dict(key=key,authors=author,title=title,year=year,url=url,verified=verified,access_level=level,checked_locator_and_scope=scope,date_evidence=dates,accessed='2026-11-19',reviewer='root'))
 fields={'author':author,'title':title,'year':year,'note':'verified' if verified else 'unverified'}
 if url:fields['url']=url
 # A separate evidence file carries qualification; note remains the requested flag.
 bib.append('@misc{'+key+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items())+'\n}\n')
 et='used and rechecked in this run' if verified and level not in ['metadata only','metadata and indirect primary quotation'] else 'carried as background without fault found'
 events.append([key,now,'GPT-6 Astra Pro; effort not exposed; SA15-20261119/root',et,level+': '+scope])
